import threading
class SingletonMeta(type):
    _instances = {}
    _lock = threading.Lock()
    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            with cls._lock:
                if cls not in cls._instances:
                    cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

import re
def parse_semver(v: str) -> dict:
    pattern = r'^(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)(?:-(?P<prerelease>[0-9A-Za-z.-]+))?(?:\+(?P<buildmetadata>[0-9A-Za-z.-]+))?$'
    m = re.match(pattern, v)
    if not m: raise ValueError(f'Invalid semver: {v}')
    d = m.groupdict()
    return {'major': int(d['major']), 'minor': int(d['minor']), 'patch': int(d['patch']), 'prerelease': d['prerelease'], 'buildmetadata': d['buildmetadata']}

from collections import deque
def topological_sort(nodes, edges):
    indegree = {n: 0 for n in nodes}
    adj = {n: [] for n in nodes}
    for u, v in edges:
        adj[u].append(v)
        indegree[v] += 1
    q = deque([n for n, deg in indegree.items() if deg == 0])
    order = []
    while q:
        curr = q.popleft()
        order.append(curr)
        for nxt in adj[curr]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0: q.append(nxt)
    if len(order) != len(nodes): raise ValueError('Graph has cycles')
    return order

from pathlib import Path
import json
def find_active_records(root_dir: str):
    for path in Path(root_dir).rglob('*.json'):
        try:
            with path.open('r', encoding='utf-8') as f:
                data = json.load(f)
                if isinstance(data, list):
                    for item in data:
                        if item.get('status') == 'active': yield item
                elif isinstance(data, dict) and data.get('status') == 'active':
                    yield data
        except (json.JSONDecodeError, OSError):
            continue

